typeDefinitions.declaration:
export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: "primary" | "secondary" | "quiet" | "danger";
  size?: Size;
  /**
   * Why the action is unavailable, used while the button is disabled. It is the button's
   * accessible description (aria-describedby) and follows the label text in title as
   * "label — reason", so a label cut by the ellipsis stays readable next to the reason.
   */
  disabledReason?: string;
  /**
   * The action is running: the button says so with aria-busy and the loader icon, and a
   * further press does nothing. The busy wording is the caller's children, in the page's
   * language; the package adds no text of its own.
   */
  loading?: boolean;
}

export interface ClipboardCopyButtonProps
  extends Omit<ButtonProps, "aria-label" | "children" | "disabledReason" | "loading" | "onClick" | "type" | "value"> {
  text: string;
  ariaLabel: string;
  children?: never;
  onClick?: never;
  type?: never;
  value?: never;
  idleLabel?: string;
  copyingLabel?: string;
  copiedLabel?: string;
  failedLabel?: string;
  unsupportedLabel?: string;
  /** Which language the five built-in state labels are said in; defaults to the page's own. */
  locale?: TcrnLocale | string;
  disabledReason?: string;
  resetDelayMs?: number;
  onCopyStateChange?: (state: ClipboardCopyState) => void;
}

example.usage:
import { ClipboardCopyButton, tcrnComponentCss } from "@tcrn/ui-react/approved";
import { tcrnTokenCss } from "@tcrn/ui-tokens";
import "@tcrn/ui-tokens/fonts.css";

export function Example() {
  return <>
    <style>{tcrnTokenCss + "\n" + tcrnComponentCss}</style>
    <div data-tcrn-root data-tcrn-theme="light" style={{ display: "grid", justifyItems: "start", gap: "var(--tcrn-space-2)" }}>
      <ClipboardCopyButton text="PRJ-2026-0412" ariaLabel="Copy" locale="en"/>
    </div>
  </>;
}
